INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (84, 165, 'Bopp flower wrapping film in smaller rolls', '../upload/image/20180922/20180922163619_63577.jpg', '<p><br/></p><p><span style="font-size:18px;color:#009900;">Bopp flower wrapping film</span></p> <p><span style="font-size:18px;color:#009900;">Bopp flower wrapping film (BOPP foil or BOPP paper or superclear cellophane) in smaller rolls</span><br/> <span style="font-size:18px;color:#009900;">Thickness: 15-50UM (Microns) for example: 20 25 30 35 40 Microns</span><br/> <span style="font-size:18px;color:#009900;">Width: 90-1200MM ( such as: 500,550,600,650,700,750,800,850,950,1050,1100mm..)</span><br/> <span style="font-size:18px;color:#009900;">Length: 20,50,60,80,120,180,200,250,300,400,500,1000M</span><br/> <span style="font-size:18px;color:#009900;">Usage: Used for packing all kinds of flowers </span><br/> <span style="font-size:18px;color:#009900;">Color: Super clear transparent or red, pink, green, white, purple, blue or printed customer''s private logos.</span><br/> <span style="font-size:18px;color:#009900;">Material: BOPP clear transparent film, Silver metalized BOPP film, logo designs printed BOPP film, laser holographic film. And BOPP silver golden color film, and so forth</span><br/> <span style="font-size:18px;color:#009900;">Bopp flower wrapping film, BOPP jumbo rolls slit into the smaller rolls, and the smaller roll can be any nominated thickness, and nominated width and any nominated length, and any nominated inner paper tube core, for example: 3.0" ,2.0",1.0" . usually buyer order the smaller rolls and nominated/fixed the roll net weight and gross weight. </span><br/> <span style="font-size:18px;color:#009900;">Packing: use carton and for size 30Mic*650mm*60M ,usually 12rolls/carton </span><br/> <span style="font-size:18px;color:#009900;">For size: 30Mic*650mm*200M,usually 4rolls/carton</span><br/> <span style="font-size:18px;color:#009900;">For size: 30Mic*650mm*400M,usually 2rolls/carton</span><br/> <span style="font-size:18px;color:#009900;">Inner core: 1.0" 1.5" 1.8" 2.0" 2.5" 3.0" inches. </span><br/> <span style="font-size:18px;color:#009900;">Two end of the core will use the plastic insert to protect the rolls.</span></p> <p><strong><span style="color:#009900;font-size:18px;">See below PDF link For more details photos:</span></strong></p> <p><a class="ke-insertfile" href="../upload/file/20180925225120_59419.pdf" target="_blank"><strong><span style="color:#009900;font-size:18px;">Asia Pacific -details photos of BOPP Flower wrapping film-compressed.pdf</span></strong></a></p> <p><br/> <br/> <br/> <br/> <br/> <br/> <br/> <br/> <br/></p> <p><strong><span style="color:#009900;font-family:Verdana;font-size:16px;">See below PDF link For more details photos: </span></strong></p> <p><a class="ke-insertfile" href="../upload/file/20180925225120_59419.pdf" target="_blank"><strong><span style="color:#337FE5;font-family:Verdana;font-size:16px;">Asia Pacific -details photos of BOPP Flower wrapping film-compressed.pdf</span></strong></a></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (84, 166, 'BOPP flower wrapping film smaller roll /sheet cut size printed', '../upload/image/20180925/20180925230154_36735.jpg', '<p></p><p>BOPP flower wrapping film smaller roll /sheet cut size printed</p> <p>BOPP flower film included BOPP foil,PP flower wrapping film,bopp paper,Bopp sheets, printed pp flower film,superclear cellophane,bopp gift wrapping film,bopp printed sheets,Polypropylene wrapping film,bopp shrinkage film for flower wrapping and BOPP sleeves,BOPP bags.<br/> Smaller roll size (mini roll size), colored or printed customer''s own private logo label <br/> Thickness : 18UM,25UM ,30UM,35UM,40UM<br/> Color : Super clear(transparent ) ,golden,red ,pink ,green ,white ,purple ,blue or printed customer''s private logos <br/> Width : 500MM/600MM/700MM/800MM/1000MM,1200MM<br/> Length : 30M,60M,100M,120M,150M,180M,200M,600M,1000M <br/> Inner core :1.5inches, 1.8 inches ,2 inches ,3inches<br/> Package : Standard export package ( with cartons and pallets ), in roll: 4rolls (or 6rolls)/carton <br/> In sheets ---- 200/500pieces/pack( 1000sheets/pack),20 packs/carton , 20cartons/pallets).</p> <p><strong><span style="color:#009900;font-family:Verdana;font-size:16px;">See below PDF link For more details photos: </span></strong></p> <p><a class="ke-insertfile" href="../upload/file/20180925225120_59419.pdf" target="_blank"><strong><span style="color:#337FE5;font-family:Verdana;font-size:16px;">Asia Pacific -details photos of BOPP Flower wrapping film-compressed.pdf</span></strong></a></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (84, 249, 'BOPP COLOR PRINTED FLOWER WRAPPING FILM', '../upload/image/20180925/20180925230136_38504.jpg', '<p></p><table border="0" cellpadding="0" cellspacing="1" class="ke-zeroborder" style=''margin:0px auto;color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;'' width="100%"> <tbody> <tr> <td colspan="2" valign="middle"> <strong><span style="font-family:Tahoma;font-size:18px;">BOPP COLOR PRINTED FLOWER WRAPPING FILM</span></strong> </td> </tr> <tr> <td colspan="2" valign="middle"> </td> </tr> <tr> <td class="line_buttom_hui_xuxian" colspan="2"> <p class="hangju"> <span style="font-size:18px;"><span style=''font-family:"";''><br/> <span style="font-family:Tahoma;font-size:18px;">1.</span><br/> <span style="font-family:Tahoma;font-size:18px;">BOPP color (logo) printed film in jumbo roll . </span><br/> <span style="font-family:Tahoma;font-size:18px;">thickness : 20UM,25UM ,30UM,35UM,40UM</span><br/> <span style="font-family:Tahoma;font-size:18px;">color : red ,pink ,green,white,purple,bule ,light colors ,golden or printed customer''s own colored logos</span><br/> <span style="font-family:Tahoma;font-size:18px;">width : 350MM/400MM/500MM/600MM/700MM/800MM/1000MM</span><br/> <span style="font-family:Tahoma;font-size:18px;">length : 1000M ,3000M,4000M,6000M </span><br/> <span style="font-family:Tahoma;font-size:18px;">printed sides : one surface printed ( printed on the corona treated side) ,Or printed twice on the same side ( printed on the corona treated side once with one color , then printed on the same corona treated side with one other different color again , then can get the two color on the double sides )</span><br/> <span style="font-family:Tahoma;font-size:18px;">inner core :1.5 inch 1.8 inch ,2 inch ,3 inch,6 inch</span><br/> <span style="font-family:Tahoma;font-size:18px;">package : Standard exporting package ( with cartons and pallets ).</span><br/> <span style="font-family:Tahoma;font-size:18px;">logo designs: offered by customer or use our maintain designs .</span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;">2.</span><br/> <span style="font-family:Tahoma;font-size:18px;">BOPP color (logo) printed film in mini-smaller roll . </span><br/> <span style="font-family:Tahoma;font-size:18px;">thickness : 20UM,25UM ,30UM,35UM,40UM</span><br/> <span style="font-family:Tahoma;font-size:18px;">color : red ,pink ,green,white,purple,bule ,light colors ,golden or printed customer''s own colored logos</span><br/> <span style="font-family:Tahoma;font-size:18px;">width : 350MM/400MM/500MM/600MM/700MM/800MM/1000MM</span><br/> <span style="font-family:Tahoma;font-size:18px;">length : 15M,30M,60M,100M,120M,200M,500M,1000M</span><br/> <span style="font-family:Tahoma;font-size:18px;">printed sides : one surface printed ( printed on the corona treated side) ,Or printed twice on the same side ( printed on the corona treated side once with one color , then printed on the same corona treated side with one other different color again , then can get the two color on the double sides )</span><br/> <span style="font-family:Tahoma;font-size:18px;">inner core :1.5 inch 1.8 inch ,2 inch</span><br/> <span style="font-family:Tahoma;font-size:18px;">package : Standard exporting package ( with cartons and pallets ).</span><br/> <span style="font-family:Tahoma;font-size:18px;">logo designs: offered by customer or use our maintain designs .</span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;">3.</span><br/> <span style="font-family:Tahoma;font-size:18px;">BOPP color (logo) printed film in cutting sheets ( pages) . </span><br/> <span style="font-family:Tahoma;font-size:18px;">thickness : 20UM,25UM ,30UM,35UM,40UM</span><br/> <span style="font-family:Tahoma;font-size:18px;">color : red ,pink ,green,white,purple,bule ,light colors ,golden or printed customer''s own colored logos</span><br/> <span style="font-family:Tahoma;font-size:18px;">width : 0.6M,0.8M,1.0M,1.2M</span><br/> <span style="font-family:Tahoma;font-size:18px;">length : 0.6M,0.8M,1.0M,1.1M,1.2M</span><br/> <span style="font-family:Tahoma;font-size:18px;">printed sides : one surface printed ( printed on the corona treated side) ,Or printed twice on the same side ( printed on the corona treated side once with one color , then printed on the same corona treated side with one other different color again , then can get the two color on the double sides )</span><br/> <span style="font-family:Tahoma;font-size:18px;">inner core :1.5 inch 1.8 inch ,2 inch</span><br/> <span style="font-family:Tahoma;font-size:18px;">package : Standard exporting package ( with cartons and pallets ).</span><br/> <span style="font-family:Tahoma;font-size:18px;">logo designs: offered by customer or use our maintain designs .</span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;">Some logos for customer reference followings : </span><br/> <br/> <img alt="" border="0" height="629" src="../images/no-photo.png" width="557"/><br/> <img alt="" border="0" height="400" src="../images/no-photo.png" width="557"/><br/> <img alt="" border="0" height="423" src="../images/no-photo.png" width="446"/><br/> <img alt="" border="0" height="469" src="../images/no-photo.png" width="476"/><br/> <img alt="" border="0" height="650" src="../images/no-photo.png" width="446"/></span></span></p> <p class="hangju"> <br/></p> <p><strong><span style="color:#009900;font-family:Verdana;font-size:16px;">See below PDF link For more details photos: </span></strong></p> <p><a class="ke-insertfile" href="../upload/file/20180925225120_59419.pdf" target="_blank"><strong><span style="color:#337FE5;font-family:Verdana;font-size:16px;">Asia Pacific -details photos of BOPP Flower wrapping film-compressed.pdf</span></strong></a></p> <p><br/></p></td> </tr> </tbody> </table>', '2026-09-06 20:58:45');